using System.Text.Json;
namespace Studio;
public static class CreativeContract
{
 private static readonly Dictionary<string,Action<JsonElement,Dictionary<string,JsonElement>,List<string>,bool>> Validators=new(){["studio.storyboard.Sequence"]=Story,["studio.configurator.Catalog"]=Catalog,["studio.industrial.Review"]=Review};
 private static string T(JsonElement e,string key)=>DocumentContract.Text(e,key);
 public static void Validate(JsonElement document,List<string> errors,bool publish){var entities=document.GetProperty("entities").EnumerateArray().ToDictionary(e=>T(e,"id"));foreach(var entity in entities.Values)foreach(var component in entity.GetProperty("components").EnumerateArray())if(component.GetProperty("enabled").GetBoolean()&&Validators.TryGetValue(T(component,"type"),out var validate))validate(component.GetProperty("data"),entities,errors,publish);}
 private static void Story(JsonElement data,Dictionary<string,JsonElement> entities,List<string> errors,bool publish){
  var duration=data.GetProperty("duration").GetDouble();var tracks=data.GetProperty("tracks").EnumerateArray().ToArray();var ids=new HashSet<string>();
  foreach(var track in tracks){if(!ids.Add(T(track,"id")))errors.Add("轨道 ID 重复");var clips=track.GetProperty("clips").EnumerateArray().ToArray();foreach(var clip in clips){if(!ids.Add(T(clip,"id")))errors.Add("片段 ID 重复");var frames=clip.TryGetProperty("keyframes",out var keyframes)?keyframes.EnumerateArray().ToArray():[];var frameTimes=new HashSet<double>();foreach(var frame in frames)if(!frameTimes.Add(frame.GetProperty("time").GetDouble()))errors.Add("关键帧时间不得重复");foreach(var timed in frames.Prepend(clip))if(timed.TryGetProperty("bezier",out var handles)&&(handles[0].GetDouble()<0||handles[0].GetDouble()>1||handles[2].GetDouble()<0||handles[2].GetDouble()>1))errors.Add("Bezier 时间控制点 x 必须在 0～1");if(clip.GetProperty("curveStart").GetDouble()>clip.GetProperty("curveEnd").GetDouble())errors.Add("片段求值窗口无效");if(clip.GetProperty("start").GetDouble()+clip.GetProperty("duration").GetDouble()>duration+.000001)errors.Add("片段超出故事板时长");}
   for(var i=0;i<clips.Length;i++)for(var j=i+1;j<clips.Length;j++)if(Overlap(clips[i],clips[j]))errors.Add("同轨片段重叠");
   var channel=T(track,"channel");if(track.GetProperty("muted").GetBoolean()||clips.Length==0)continue;if(publish&&channel=="audio"&&(!entities.TryGetValue(T(track,"targetId"),out var audioTarget)||!audioTarget.GetProperty("components").EnumerateArray().Any(c=>T(c,"type")=="Audio"&&c.GetProperty("enabled").GetBoolean())))errors.Add("音频轨道目标能力不匹配");if(publish&&new[]{"transform","opacity","visibility","annotation","assembly","audio"}.Contains(channel)&&T(track,"targetId")=="")errors.Add("故事板轨道缺少目标");
   if(publish&&channel=="assembly"&&(!entities.TryGetValue(T(track,"targetId"),out var target)||!target.GetProperty("components").EnumerateArray().Any(c=>T(c,"type")=="studio.assembly.Root"&&c.GetProperty("enabled").GetBoolean())))errors.Add("装配轨道目标能力不匹配");
  }
  for(var i=0;i<tracks.Length;i++)for(var j=i+1;j<tracks.Length;j++){var a=tracks[i];var b=tracks[j];if(T(a,"targetId")==T(b,"targetId")&&T(a,"channel")==T(b,"channel")&&a.GetProperty("priority").GetDouble()==b.GetProperty("priority").GetDouble()&&!a.GetProperty("muted").GetBoolean()&&!b.GetProperty("muted").GetBoolean())foreach(var x in a.GetProperty("clips").EnumerateArray())foreach(var y in b.GetProperty("clips").EnumerateArray())if(Overlap(x,y))errors.Add("相同目标通道重叠，需要不同合成优先级");}
 }
 private static bool Overlap(JsonElement a,JsonElement b)=>a.GetProperty("start").GetDouble()<b.GetProperty("start").GetDouble()+b.GetProperty("duration").GetDouble()&&b.GetProperty("start").GetDouble()<a.GetProperty("start").GetDouble()+a.GetProperty("duration").GetDouble();
 private static void Catalog(JsonElement data,Dictionary<string,JsonElement> entities,List<string> errors,bool publish){if(publish)errors.AddRange(ConfigurationRules.Validate(data));}
 private static void Review(JsonElement data,Dictionary<string,JsonElement> entities,List<string> errors,bool publish){
  foreach(var color in data.GetProperty("colors").EnumerateArray())if(T(color,"mode")=="range"&&color.GetProperty("min").GetDouble()>=color.GetProperty("max").GetDouble())errors.Add("连续颜色范围需要递增的上下界");
  var classes=data.GetProperty("classes").EnumerateArray().ToArray();var byId=new Dictionary<string,JsonElement>();foreach(var c in classes){if(!byId.TryAdd(T(c,"id"),c))errors.Add("分类 ID 重复");if(c.GetProperty("fields").EnumerateArray().Select(f=>T(f,"id")).Distinct().Count()!=c.GetProperty("fields").GetArrayLength())errors.Add("属性字段 ID 重复");}
  foreach(var c in classes){var seen=new HashSet<string>();var cursor=c;while(true){if(!seen.Add(T(cursor,"id"))){errors.Add("分类层级循环");break;}var parent=T(cursor,"parentId");if(parent=="")break;if(!byId.TryGetValue(parent,out cursor)){errors.Add("分类父项不存在");break;}}}
  if(publish)foreach(var measurement in data.GetProperty("measurements").EnumerateArray())if(measurement.TryGetProperty("anchorRefs",out var anchors))foreach(var anchor in anchors.EnumerateArray()){
   if(!entities.TryGetValue(T(anchor,"entityId"),out var entity)){errors.Add("测量目标丢失");continue;}var binding=entity.GetProperty("components").EnumerateArray().FirstOrDefault(c=>T(c,"type")=="ModelNode"&&c.GetProperty("enabled").GetBoolean());if(T(anchor,"sourceRevision")!=""&&(binding.ValueKind==JsonValueKind.Undefined||T(binding.GetProperty("data"),"meshRevision")!=T(anchor,"sourceRevision"))||T(anchor,"sourceElementId")!=""&&(binding.ValueKind==JsonValueKind.Undefined||T(binding.GetProperty("data"),"sourceElementId")!=T(anchor,"sourceElementId")))errors.Add("测量来源已变化");
  }
 }
}
